function buildG10() {
  let seed = 1010; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const sh = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const cl = t => { let c = t.split(/;\s/)[0].replace(/\.$/, ""); if (c.length > 110) { c = c.slice(0, 110); c = c.slice(0, c.lastIndexOf(" ")) + "…"; } return c; };
  const fulls = [...new Set(G10_ROWS.map(r => r[1]))];
  return G10_ROWS.map((r, i) => {
    const [display, full, title, text, page, sec, note] = r, s = G10_SECS[sec], c = cl(text);
    const o1 = [full, ...sh(fulls.filter(f => f !== full)).slice(0, 3)];
    const o2 = [c, ...sh(G10_ROWS.filter(x => x[1] !== full)).slice(0, 3).map(x => cl(x[3]))];
    const tf = rnd() < 0.5, fake = sh(G10_ROWS.filter(x => x[1] !== full))[0][1];
    const parts = text.split(/;\s+/).map(p => p.trim().replace(/\.$/, "")).filter(Boolean).map(p => p.charAt(0).toUpperCase() + p.slice(1) + ".");
    const facts = parts.slice(1);
    return { id: "10-" + String(i + 1).padStart(3, "0"), display, title, teaser: text, summary: parts[0] || text, facts,
      quiz: [
        { q: "«" + c + "» — оқулықта қай мерзімге жатқызылған?", o: o1, a: 0 },
        { q: "Оқулық бойынша «" + full + "» мерзіміне қатысты қай мәлімет дұрыс?", o: o2, a: 0 },
        { q: "Дұрыс па: «" + c + "» — " + (tf ? full : fake) + ".", o: ["Дұрыс", "Бұрыс"], a: tf ? 0 : 1 }
      ] };
  });
}
