function buildG11() {
  let seed = 1111; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const sh = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const cl = t => { let c = t.split(/;\s|(?<=[а-яәғқңөұүһіё0-9»)])\.\s/)[0].replace(/\.$/, ""); if (c.length > 120) { c = c.slice(0, 120); c = c.slice(0, c.lastIndexOf(" ")) + "…"; } return c; };
  const nums = s => (s.match(/\d{3,4}/g) || []);
  const far = (a, b) => Math.abs(a[4] - b[4]) >= 8 && !nums(a[1]).some(n => nums(b[1]).includes(n)) && a[0] !== b[0];
  return G11_ROWS.map((r, i) => {
    const [display, full, title, text] = r, c = cl(text);
    const pool = sh(G11_ROWS.filter(x => far(x, r)));
    const dates = []; for (const x of pool) { if (dates.length === 3) break; if (!dates.includes(x[1]) && dates.every(d => !nums(d).some(n => nums(x[1]).includes(n)))) dates.push(x[1]); }
    const infos = pool.slice(0, 3).map(x => cl(x[3]));
    const tf = rnd() < 0.5;
    const parts = text.split(/;\s+/).map(p => p.trim().replace(/\.$/, "")).filter(Boolean).map(p => p.charAt(0).toUpperCase() + p.slice(1) + ".");
    return { id: "11-" + String(i + 1).padStart(3, "0"), display, title, teaser: text, summary: parts[0] || text, facts: parts.slice(1),
      quiz: [
        { q: "«" + c + "» — бұл қай мерзімде болды?", o: [full, ...dates], a: 0 },
        { q: "«" + full + "» мерзіміне қатысты қай мәлімет дұрыс?", o: [c, ...infos], a: 0 },
        { q: "Дұрыс па: «" + c + "» — " + (tf ? full : dates[0]) + ".", o: ["Дұрыс", "Бұрыс"], a: tf ? 0 : 1 }
      ] };
  });
}
